return [
  {
    json: {
      workflow: {
        id: "WF-0008",
        name: "Object Loader",
        version: "0.2.0",
        status: "development"
      },

      source: {
        system: "GitHub",
        owner: "Jamoko112026",
        repository: "JaMoKo_OS",
        branch: "main",
        root: "01_Objects",
        fileName: "object.md"
      },

      validation: {
        requiredFields: [
          "objectId",
          "objectType",
          "title",
          "status"
        ]
      },

      normalization: {
        objectIdUppercase: true,
        objectTypeLowercase: true,
        defaultPriority: "normal"
      }
    }
  }
];

const response = $input.first().json;
const config = $("02-Load Configuration").first().json;

const tree = response.tree || [];

const files = tree
  .filter(item =>
    item.type === "blob" &&
    item.path.startsWith(config.source.root + "/") &&
    item.path.endsWith("/" + config.source.fileName)
  )
  .map(item => ({
    path: item.path,
    sha: item.sha,
    url: item.url
  }));

return [
  {
    json: {
      ...config,
      repositorySha: response.sha,
      fileCount: files.length,
      files
    }
  }
];

const requiredFields = [
  "objectId",
  "objectType",
  "title",
  "status"
];

const parsed = $json.parsed ?? {};

const missingFields = requiredFields.filter((field) => {
  const value = parsed[field];

  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ""
  );
});

return {
  json: {
    ...$json,

    validation: {
      valid: missingFields.length === 0,
      missingFields
    }
  }
};

const items = $input.all();

const validObjects = [];
const invalidObjects = [];

for (const item of items) {
  const data = item.json;

  if (data.validation?.valid) {
    validObjects.push({
      ...data.normalized,
      meta: {
        path: data.path ?? null,
        sha: data.sha ?? null,
        sourceUrl: data.url ?? null
      }
    });
  } else {
    invalidObjects.push({
      path: data.path ?? null,
      objectId: data.parsed?.objectId ?? null,
      missingFields: data.validation?.missingFields ?? [],
      reason: "Pflichtfelder fehlen"
    });
  }
}

return [
  {
    json: {
      validObjects,
      invalidObjects,
      counts: {
        total: items.length,
        valid: validObjects.length,
        invalid: invalidObjects.length
      }
    }
  }
];

const input = $input.first().json;

const validObjects = Array.isArray(input.validObjects)
  ? input.validObjects
  : [];

const invalidObjects = Array.isArray(input.invalidObjects)
  ? input.invalidObjects
  : [];

const operationsObjects = validObjects.map((object) => ({
  objectId: object.objectId,
  objectType: object.objectType,
  title: object.title,
  status: object.status,
  description: object.description,
  source: object.source,
  priority: object.priority,

  meta: {
    path: object.meta?.path ?? null,
    sha: object.meta?.sha ?? null,
    sourceUrl: object.meta?.sourceUrl ?? null,
    loaderWorkflowId: "WF-0008",
    loaderWorkflowVersion: "0.2.0"
  }
}));

return [
  {
    json: {
      workflow: {
        id: "WF-0008",
        name: "Object Loader",
        version: "0.2.0",
        status: "development"
      },

      source: {
        system: "GitHub",
        repository: "JaMoKo_OS",
        branch: "main"
      },

      operationsObjects,

      counts: {
        totalObjects: input.counts?.total ?? 0,
        validObjects: input.counts?.valid ?? 0,
        invalidObjects: input.counts?.invalid ?? 0,
        outputObjects: operationsObjects.length
      },

      invalidObjects
    }
  }
];

const markdown = String($json.markdown ?? "");

// Zugehörigen Dateipfad aus dem Split-Node übernehmen.
const sourceFile = $("05 – Split Object Files").item.json;
const path = sourceFile.path ?? null;

function readIdentityField(label) {
  const pattern = new RegExp(
    `^${label}\\s*:\\s*(.+)$`,
    "im"
  );

  return markdown.match(pattern)?.[1]?.trim() ?? null;
}

function readSection(heading) {
  const pattern = new RegExp(
    `^##\\s+${heading}\\s*\\n([\\s\\S]*?)(?=^---\\s*$|^##\\s+|$)`,
    "im"
  );

  return markdown.match(pattern)?.[1]?.trim() ?? "";
}

const objectId =
  readIdentityField("ID") ??
  path?.match(/[A-Z]+-\d{4}/i)?.[0]?.toUpperCase() ??
  null;

const objectType =
  readIdentityField("Typ") ??
  path?.split("/")?.[1] ??
  null;

const title =
  readIdentityField("Name") ??
  markdown.match(/^#\s+(.+)$/m)?.[1]?.trim() ??
  objectId;

const status = readIdentityField("Status");

const descriptionSection = readSection("Beschreibung");

// Nur den ersten beschreibenden Absatz verwenden.
const description = descriptionSection
  .split(/\n\s*\n/)
  .map(block => block.trim())
  .find(block =>
    block !== "" &&
    !block.endsWith(":")
  ) ?? "";

return {
  json: {
    ...$json,

    path,

    parsed: {
      objectId,
      objectType,
      title,
      status,
      description,
      source: "JaMoKo OS",
      priority: "normal"
    },

    sections: {
      identity: readSection("Identität"),
      description: descriptionSection,
      relationships: readSection("Beziehungen"),
      decisions: readSection("Entscheidungen"),
      standards: readSection("Standards"),
      history: readSection("Historie"),
      attachments: readSection("Anhänge")
    },

    body: markdown
  }
};

const encodedContent = String($json.content ?? "");

if (!encodedContent) {
  throw new Error("GitHub-Blob enthält keinen Base64-Inhalt.");
}

const markdown = Buffer
  .from(encodedContent.replace(/\n/g, ""), "base64")
  .toString("utf8");

const sourceFile = $("05 – Split Object Files").item.json;

return {
  json: {
    ...$json,
    path: sourceFile.path ?? null,
    sourceSha: sourceFile.sha ?? null,
    sourceUrl: sourceFile.url ?? null,
    markdown
  }
};

const input = $input.first().json;

return [
  {
    json: {
      summary: {
        totalObjects: input.counts.totalObjects,
        validObjects: input.counts.validObjects,
        invalidObjects: input.counts.invalidObjects,
        outputObjects: input.counts.outputObjects,
      },

      repairs: input.invalidObjects.map(obj => ({
        objectId: obj.objectId,
        path: obj.path,
        missing: obj.missingFields,
      })),
    },
  },
];

const input = $input.first().json;

const summary = input.summary ?? {};
const repairs = Array.isArray(input.repairs)
  ? input.repairs
  : [];

const invalidObjects = repairs.length;

let runStatus = "success";

if (invalidObjects > 0) {
  runStatus = "warning";
}

if (
  summary.totalObjects === 0 ||
  summary.totalObjects === undefined
) {
  runStatus = "error";
}

return [
  {
    json: {
      workflow: {
        id: "WF-0008",
        name: "Object Loader",
        version: "0.2.0",
        status: "development"
      },

      runStatus,

      summary: {
        totalObjects: summary.totalObjects ?? 0,
        validObjects: summary.validObjects ?? 0,
        invalidObjects: summary.invalidObjects ?? invalidObjects,
        outputObjects: summary.outputObjects ?? 0,
        repairItems: repairs.length
      },

      repairRequired: repairs.length > 0,

      repairs,

      safety: {
        readOnly: true,
        filesChanged: false,
        commitsCreated: false,
        automaticRepair: false
      },

      nextWorkflow: repairs.length > 0
        ? {
            id: "WF-0009",
            name: "Object Repair Engine",
            action: "review_repair_proposals"
          }
        : null,

      timestamp: new Date().toISOString()
    }
  }
];
